// Viable PWA service worker (generated by scripts/build-pwa.mjs; do not edit
// the built copy). ADR-0010 update contract:
// - every build has an immutable BUILD_ID and its own cache;
// - a new worker waits until the person confirms the update (no automatic
//   skipWaiting), so code is never swapped under a running session;
// - old build caches are deleted only after the new worker activates;
// - the worker never reads, uploads, or caches workspace data; it caches only
//   the application shell listed in PRECACHE.

const BUILD_ID = "__VIABLE_BUILD_ID__";
const CACHE = `viable-shell-${BUILD_ID}`;
const PRECACHE = __VIABLE_PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((path) => new Request(path, { cache: "reload" })))),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((name) => name.startsWith("viable-shell-") && name !== CACHE).map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "VIABLE_ACTIVATE_UPDATE") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  // Only the same-origin application shell is served from cache. Everything
  // else (for example public GitHub reads) goes to the network untouched.
  if (url.origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // build-info.json is served from the same cache as the running code, so
    // the app always reports the build it is actually executing.
    if (request.mode === "navigate") {
      const shell = await cache.match("index.html");
      if (shell) return shell;
    }
    const cached = await cache.match(request, { ignoreSearch: true });
    return cached ?? fetch(request);
  })());
});
